"""Construction LEDGER: aggregate results/construct*/<scenario>_s<seed>.json into one markdown table (what was supplied, what
emerged, validity) -> results/construct/LEDGER.md.  usage: ledger.py [dir ...]"""
import sys, os, json, glob; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); from engine import core
dirs = sys.argv[1:] or [f"{core.RES}/construct", f"{core.RES}/construct_full"]; rows = []
for d in dirs:
    for f in sorted(glob.glob(f"{d}/*_s*.json")):
        x = json.load(open(f)); r = x["result"]; e = x.get("emerged") or {}; sup = x["supplied"]; eff = sup["effect"]
        rows.append(dict(scenario=x["scenario"], seed=x["seed"], evals=sup["budget"]["evals"], effector=eff["effector"], support=eff["support"], direction=eff.get("direction"), speed=round(r["value"], 2), valid=r["valid_both_dt"], reasons=",".join(r["reasons"]) or "-",
                         peaks=e.get("peak_omega"), order=("p->d" if e.get("strict_proximal_to_distal") else "mixed") if e else None, own={k: v for k, v in (e.get("ownership_group") or {}).items() if abs(v) >= 0.3}, base=round(e.get("ownership_base", 0), 1) if e else None,
                         beyond=e.get("beyond_human"), W=e.get("W_pos"), prep=sup.get("prior_steps", {}).get("prep"), amp=round(r.get("amp") or 0, 2), tscale=round(r.get("tscale") or 0, 2), secs=r.get("secs"), file=os.path.relpath(f, core.RES)))
rows.sort(key=lambda r: (r["scenario"], r["evals"], r["seed"]))
L = ["# Construction ledger (auto-generated by engine/ledger.py)", "", "One procedure (engine/construct.py), one physical effect per row; nothing task-specific beyond the effect spec. Speeds in m/s at release; valid = both timesteps pass every gate (support feet loaded, cone, actuator envelope, energy closure). Ownership = release-speed share by joint group (J qdot along the release direction). beyond-human = joints driven past a human range of motion.", "",
     "| scenario | seed | evals | effector/support | speed | valid | reasons | chain peaks (rad/s) | order | ownership (m/s) | base | beyond human | W+ by group (J) | prep | amp | tscale | s |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in rows:
    L.append(f"| {r['scenario']} | {r['seed']} | {r['evals']} | {r['effector']}/{r['support']} | {r['speed']} | {'yes' if r['valid'] else 'NO'} | {r['reasons']} | {r['peaks']} | {r['order']} | {r['own']} | {r['base']} | {','.join(r['beyond'] or []) or '-'} | {({k: round(v) for k, v in (r['W'] or {}).items()})} | {r['prep']} | {r['amp']} | {r['tscale']} | {r['secs']} |")
open(f"{core.RES}/construct/LEDGER.md", "w").write("\n".join(L) + "\n"); print("\n".join(L[5:])); print(f"-> {core.RES}/construct/LEDGER.md ({len(rows)} rows)")
